import java.util.*;

class Solution {
    public boolean hasPathSum(TreeNode root, int target) {
        if (root == null) return false;
        if (root.left == null && root.right == null) return root.val == target; // leaf check
        int rest = target - root.val;  // what is still needed below this node
        return hasPathSum(root.left, rest) || hasPathSum(root.right, rest);
    }
}

