function hasPathSum(root, target) {
  const st = root ? [[root, root.val]] : [];
  while (st.length) {
    const [n, s] = st.pop();
    if (!n.left && !n.right && s === target) return true;
    if (n.left) st.push([n.left, s + n.left.val]);
    if (n.right) st.push([n.right, s + n.right.val]);
  }
  return false;
}
